<script setup lang="ts">
import { Plus, Pencil, UsersRound } from '@lucide/vue'
import type { Doctor } from '../domain/types'
import { saveDoctor } from '../domain/commands'
import { prettyDate } from '../domain/calendar'
const w = useWorkspace(), edit = ref<Doctor | null>(null)
function open(d?: Doctor) { edit.value = d ? JSON.parse(JSON.stringify(d)) : { id: crypto.randomUUID(), name: '', phone: '', unit: 'rotasi', active: true, joinedOn: null, leave: [] } }
async function submit() { if (!edit.value) return; const d = { ...edit.value, name: edit.value.name.trim(), joinedOn: edit.value.joinedOn || null }; if (await w.mutate(data => saveDoctor(data, d, w.role.value), `Menyimpan dokter ${d.name}`, true)) edit.value = null }
</script>
<template>
  <PageHeading title="Daftar dokter" subtitle="Kelola nama, layanan, tanggal bergabung, dan periode cuti dokter." eyebrow="Tim pelayanan"><button v-if="w.isAdmin.value" class="btn btn-primary" :disabled="w.saving.value" @click="open()"><Plus :size="16"/>Tambah dokter</button></PageHeading>
  <div class="panel overflow-hidden"><div class="scrollbar-thin overflow-x-auto"><table class="w-full text-left text-xs"><thead class="table-head"><tr><th class="px-5 py-4">No.</th><th class="px-4 py-4">Nama dokter</th><th class="px-4 py-4">Layanan</th><th class="px-4 py-4">Mulai bergabung</th><th class="px-4 py-4">Cuti</th><th class="px-4 py-4">Status</th><th class="px-4 py-4"><span class="sr-only">Aksi</span></th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="(d, i) in w.data.value?.doctors" :key="d.id"><td class="px-5 py-5 text-slate-400">{{ i + 1 }}</td><td class="min-w-40 px-4 py-5"><p class="font-semibold">{{ d.name }}</p><p v-if="w.isAdmin.value && d.phone" class="mt-1 text-[11px] text-slate-400">{{ d.phone }}</p></td><td class="px-4 py-5"><span class="tag" :class="d.unit === 'anak' ? 'bg-lime-50 text-lime-700' : 'bg-brand-50 text-brand-700'">{{ d.unit === 'anak' ? 'Khusus ruang anak' : 'Rotasi layanan' }}</span></td><td class="whitespace-nowrap px-4 py-5 text-slate-500">{{ d.joinedOn ? prettyDate(d.joinedOn) : 'Sebelum periode ini' }}</td><td class="min-w-40 px-4 py-5"><p v-for="l in d.leave" :key="l.from" class="text-[11px] leading-relaxed text-slate-500">{{ prettyDate(l.from) }} – {{ prettyDate(l.to) }}</p><span v-if="!d.leave.length" class="text-slate-300">—</span></td><td class="px-4 py-5 text-slate-400">{{ d.active ? 'Aktif' : 'Nonaktif' }}</td><td class="px-4 py-5"><button v-if="w.isAdmin.value" class="rounded-lg p-2 text-slate-400 hover:bg-brand-50 hover:text-brand-700" :aria-label="`Edit ${d.name}`" @click="open(d)"><Pencil :size="15"/></button></td></tr></tbody></table></div></div>
  <p class="mt-4 text-xs leading-relaxed text-slate-400">Nama dokter yang sama tetap memakai ID yang sama, sehingga pergantian nama tidak memutus jadwal. Setelah memperbarui cuti, sesuaikan isian dinas yang sudah terlanjur dibuat.</p>
  <AppModal v-if="edit" title="Data dokter" @close="edit = null"><form class="space-y-4" @submit.prevent="submit"><div><label for="doctor-name" class="label">Nama dokter</label><input id="doctor-name" v-model="edit.name" class="field" required maxlength="100" placeholder="dr. Nama Dokter"/></div><div><label for="doctor-phone" class="label">Nomor HP (opsional)</label><input id="doctor-phone" v-model="edit.phone" class="field" inputmode="tel" maxlength="30"/></div><div class="grid grid-cols-2 gap-4"><div><label for="doctor-unit" class="label">Layanan</label><select id="doctor-unit" v-model="edit.unit" class="field"><option value="rotasi">Rotasi layanan</option><option value="anak">Ruang anak saja</option></select></div><div><label for="doctor-joined" class="label">Mulai bergabung</label><input id="doctor-joined" v-model="edit.joinedOn" type="date" class="field"/></div></div><div><div class="mb-3 flex items-center justify-between"><p class="label mb-0">Periode cuti</p><button type="button" class="text-xs font-semibold text-brand-700" @click="edit.leave.push({ from: '', to: '' })">Tambah periode</button></div><div v-for="(l, i) in edit.leave" :key="i" class="mb-2 grid grid-cols-[1fr_1fr_auto] items-center gap-2"><input v-model="l.from" class="field" type="date" required :aria-label="`Mulai cuti ${i+1}`"/><input v-model="l.to" class="field" type="date" required :min="l.from" :aria-label="`Selesai cuti ${i+1}`"/><button type="button" class="p-1 text-xs text-slate-400" aria-label="Hapus periode cuti" @click="edit.leave.splice(i, 1)">Hapus</button></div><p v-if="!edit.leave.length" class="rounded-xl bg-slate-50 p-3 text-xs text-slate-400">Belum ada cuti.</p></div><label class="flex items-center gap-2 text-xs text-slate-500"><input v-model="edit.active" type="checkbox"/>Dokter aktif untuk jadwal baru</label><div class="flex justify-end gap-2 pt-2"><button type="button" class="btn btn-secondary" @click="edit = null">Batal</button><button class="btn btn-primary" :disabled="w.saving.value">Simpan dokter</button></div></form></AppModal>
</template>
